void kernel_correlation(int m, int n, float *data, float *symmat, float *mean, float *stddev) {
    // Mean calculation
    #pragma omp parallel for reduction(+:mean[0:m])
    for (int j = 0; j < m; j++) {
        double sum = 0.0;
        for (int i = 0; i < n; i++) {
            sum += data[i*m + j];
        }
        mean[j] = sum / n;
    }

    // Standard deviation calculation
    #pragma omp parallel for reduction(+:stddev[0:m])
    for (int j = 0; j < m; j++) {
        double sum_of_squares = 0.0;
        for (int i = 0; i < n; i++) {
            sum_of_squares += (data[i*m + j] - mean[j]) * (data[i*m + j] - mean[j]);
        }
        stddev[j] = sqrt(sum_of_squares / (n - EPSILON));
    }

    // Centering and reducing data
    #pragma omp parallel for
    for (int j = 0; j < m; j++) {
        for (int i = 0; i < n; i++) {
            symmat[i*m + j] = (data[i*m + j] - mean[j]) / sqrt(float(n) * stddev[j]);
        }
    }

    // Correlation matrix calculation
