        for (int j = 0; j < m; j++) {
            symmat[i*m + j] = symmat[i*m + j] * symmat[j*m + j];
        }
    }

    // Finalization
    for (int i = 0; i < m; i++) {
        symmat[i*m + i] = 1.0;
    }
