#include <omp.h>
#include <stdio.h>

#define N 1024

typedef double DATA_TYPE;

static void kernel_ludcmp(int n, DATA_TYPE POLYBENCH_2D(A, N+1, N+1, n+1, n+1), DATA_TYPE POLYBENCH_1D(b, N+1, n+1), DATA_TYPE POLYBENCH_1D(x, N+1, n+1), DATA_TYPE POLYBENCH_1D(y, N+1, n+1)) {
    int i, j, k;
    double w;

    // Initialize b
    b[0] = 1.0;

    // Parallelize the outer loop over rows
    #pragma omp parallel for collapse(2)
    for (i = 0; i < n; i++) {
        for (j = 0; j <= i; j++) {
            w = A[i][j];
            for (k = 0; k < j; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
        #pragma omp critical
        {
            // Synchronize threads
            #pragma omp atomic
            b[i] += A[i][i];
        }
        for (j = i + 1; j < n; j++) {
            w = A[i][j];
            for (k = 0; k < i; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Solve for y
    for (i = 0; i < n; i++) {
        y[i] = b[i];
    }
    for (i = 1; i < n; i++) {
        y[i] -= y[i - 1] * A[i - 1][i];
    }
    y[n - 1] /= A[n - 1][n - 1];

    // Back substitution
    x[n - 1] = y[n - 1];
    for (i = n - 2; i >= 0; i--) {
        x[i] = y[i];
        for (j = i + 1; j < n; j++) {
            x[i] -= x[j] * A[i][j];
        }
        x[i] /= A[i][i];
    }
}

