    int i, j, k;
    #pragma scop
    #pragma omp parallel for private(j, i)
    for (k = 0; k < n - 1; k++) {
        // Normalize the pivot element
        DATA_TYPE pivot = A[k][k];
        for (j = k + 1; j < n; j++) {
            A[j][k] /= pivot;
        }

        // Perform the rank-1 update
        for (i = k + 1; i < n; i++) {
            for (j = k + 1; j < n; j++) {
                A[i][j] -= A[i][k] * A[j][k];
            }
        }
    }
    #pragma endscop
}

